            if (FormLinkInformation.TryFactory(obj.Entitlement, out var EntitlementInfo))
            {
                yield return EntitlementInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Category, out var CategoryInfo))
            {
                yield return CategoryInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Animation, out var AnimationInfo))
            {
                yield return AnimationInfo;
            }
            if (obj.Keywords is {} KeywordsItem)
