        public void DeepCopyIn(
            IEmote item,
            IEmoteGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout76MajorRecord)item,
                (IFallout76MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.EDID) ?? true))
            {
                item.EDID = rhs.EDID;
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.ObjectBounds) ?? true))
            {
                errorMask?.PushIndex((int)Emote_FieldIndex.ObjectBounds);
                try
                {
                    if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.ObjectBounds) ?? true))
                    {
                        item.ObjectBounds = rhs.ObjectBounds.DeepCopy(
                            copyMask: copyMask?.GetSubCrystal((int)Emote_FieldIndex.ObjectBounds),
                            errorMask: errorMask);
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.XALG) ?? true))
            {
                if(rhs.XALG is {} XALGrhs)
                {
                    item.XALG = XALGrhs.ToArray();
                }
                else
                {
                    item.XALG = default;
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.FULL) ?? true))
            {
                item.FULL = rhs.FULL?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.Entitlement) ?? true))
            {
                item.Entitlement.SetTo(rhs.Entitlement.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.SNAM) ?? true))
            {
                item.SNAM = rhs.SNAM;
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.XFLG) ?? true))
            {
                item.XFLG = rhs.XFLG;
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.Category) ?? true))
            {
                item.Category.SetTo(rhs.Category.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.Animation) ?? true))
            {
                item.Animation.SetTo(rhs.Animation.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.ACTV) ?? true))
            {
                item.ACTV = rhs.ACTV?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.Keywords) ?? true))
            {
                errorMask?.PushIndex((int)Emote_FieldIndex.Keywords);
                try
                {
                    if ((rhs.Keywords != null))
                    {
                        item.Keywords = 
                            rhs.Keywords
                                .Select(b => (IFormLinkGetter<IKeywordGetter>)new FormLink<IKeywordGetter>(b.FormKey))
                            .ToExtendedList<IFormLinkGetter<IKeywordGetter>>();
                    }
                    else
                    {
                        item.Keywords = null;
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Emote_FieldIndex.FNAM) ?? true))
            {
                item.FNAM = rhs.FNAM;
            }
            DeepCopyInCustom(
                item: item,
                rhs: rhs,
                errorMask: errorMask,
                copyMask: copyMask,
                deepCopy: deepCopy);
        }
        
